/* The tables of M22 · Online payments and reconciliation. */

/** One attempt to pay online. */
export const paymentIntents = defineTable(
  'payment_intents',
  {
    module: 'M22',
    scope: 'branch',
    household: true,
    householdRule: { read: true, insert: { status: 'created' } },
  },
  {
    ...baseColumns,
    branchId: branchIdColumn(),
    /** from the `payment_intent` sequence; sent to the provider as our order reference */
    intentNo: text().notNull(),
    familyId: uuid()
      .references((): AnyPgColumn => families.id)
      .notNull(),
    purpose: enumText(paymentIntentPurposes).notNull().default('fees'),
    /** required for `wallet_top_up` */
    studentId: uuid().references((): AnyPgColumn => students.id),
    challanNo: text(),
    /** empty means "allocate automatically" */
    voucherIds: uuid()
      .array()
      .notNull()
      .default(sql`'{}'`),
    amount: paisa().notNull(),
    /** a convenience charge added for the payer, when the school passes it on */
    serviceCharge: paisa().notNull().default(0),
    provider: enumText(paymentIntentProviders).notNull(),
    status: enumText(paymentIntentStatuses).notNull().default('created'),
    checkoutUrl: text(),
    expiresAt: timestamptz().notNull(),
    startedBy: uuid().references((): AnyPgColumn => profiles.id),
    startedFrom: enumText(paymentIntentStartedFromOptions).notNull(),
    providerTxnId: text(),
    failureCode: text(),
    failureMessage: text(),
    /** set on success */
    paymentId: uuid().references((): AnyPgColumn => feePayments.id),
  },
  (t) => [
    check(
      'payment_intents_student_id_needed',
      sql`${t.purpose} <> 'wallet_top_up' or ${t.studentId} is not null`,
    ),
    positive('payment_intents', t.amount),
    nonNegative('payment_intents', t.serviceCharge),
    uniqueIndex('payment_intents_intent_no_uq').on(t.orgId, t.intentNo).where(live(t)),
    index('payment_intents_status_expires_at_idx').on(t.orgId, t.status, t.expiresAt),
    index('payment_intents_family_idx').on(t.orgId, t.familyId),
  ],
);

/** Everything a provider told us, one row per provider transaction. */
export const gatewayTransactions = defineTable(
  'gateway_transactions',
  { module: 'M22', scope: 'org', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    provider: text().notNull(),
    providerTxnId: text().notNull(),
    kind: enumText(gatewayTransactionKinds).notNull(),
    intentId: uuid().references((): AnyPgColumn => paymentIntents.id),
    /** 1BILL payments arrive with the consumer number only */
    challanNo: text(),
    amount: paisa().notNull(),
    occurredAt: timestamptz().notNull(),
    webhookEventId: uuid().references((): AnyPgColumn => webhookEvents.id),
    outcome: enumText(gatewayTransactionOutcomes).notNull(),
    reviewReason: text(),
    paymentId: uuid().references((): AnyPgColumn => feePayments.id),
    settlementId: uuid().references((): AnyPgColumn => settlements.id),
  },
  (t) => [
    nonNegative('gateway_transactions', t.amount),
    uniqueIndex('gateway_transactions_provider_provider_txn_kind_uq').on(
      t.orgId,
      t.provider,
      t.providerTxnId,
      t.kind,
    ),
  ],
);

/** A provider's payout to the school's bank account, net of its charges. */
export const settlements = defineTable(
  'settlements',
  { module: 'M22', scope: 'org' },
  {
    ...baseColumns,
    provider: text().notNull(),
    settlementRef: text().notNull(),
    settlementDate: dateStr().notNull(),
    gross: paisa().notNull(),
    charges: paisa().notNull().default(0),
    taxOnCharges: paisa().notNull().default(0),
    /** `gross - charges - tax_on_charges` */
    net: paisa().notNull(),
    bankAccountId: uuid()
      .references((): AnyPgColumn => bankAccounts.id)
      .notNull(),
    transactionCount: integer().notNull().default(0),
    status: enumText(settlementStatuses).notNull().default('expected'),
    /** the provider's settlement report */
    fileId: uuid().references((): AnyPgColumn => files.id),
  },
  (t) => [
    nonNegative('settlements', t.gross),
    nonNegative('settlements', t.charges),
    nonNegative('settlements', t.taxOnCharges),
    nonNegative('settlements', t.net),
    uniqueIndex('settlements_provider_settlement_ref_uq')
      .on(t.orgId, t.provider, t.settlementRef)
      .where(live(t)),
  ],
);

