export const reconciliationRules = defineTable(
  'reconciliation_rules',
  { module: 'M22', scope: 'org' },
  {
    ...baseColumns,
    name: text().notNull(),
    /** empty means every account */
    bankAccountId: uuid().references((): AnyPgColumn => bankAccounts.id),
    matchField: enumText(reconciliationRuleMatchFields).notNull(),
    /** a regular expression; the first group is the captured value */
    pattern: text().notNull(),
    captures: enumText(reconciliationRuleCaptureses).notNull(),
    /** for `none`, what the line is (bank charges, profit, transfer) */
    targetType: text(),
    /** where a line with no target is posted */
    accountId: uuid().references((): AnyPgColumn => accounts.id),
    priority: integer().notNull().default(100),
    isActive: boolean().notNull().default(true),
  },
);

/** The formal statement that a bank account agrees with the books at a date. */
export const bankReconciliations = defineTable(
  'bank_reconciliations',
  { module: 'M22', scope: 'org' },
  {
    ...baseColumns,
    bankAccountId: uuid()
      .references((): AnyPgColumn => bankAccounts.id)
      .notNull(),
    asOf: dateStr().notNull(),
    statementBalance: paisa().notNull(),
    /** computed */
    ledgerBalance: paisa().notNull(),
    /** in the books, not yet at the bank */
    outstandingDeposits: paisa().notNull().default(0),
    outstandingPayments: paisa().notNull().default(0),
    /** must be zero to complete */
    difference: paisa().notNull(),
    status: enumText(bankReconciliationStatuses).notNull().default('open'),
    completedBy: uuid().references((): AnyPgColumn => profiles.id),
    documentId: uuid().references((): AnyPgColumn => generatedDocuments.id),
  },
  (t) => [
    nonNegative('bank_reconciliations', t.outstandingDeposits),
    nonNegative('bank_reconciliations', t.outstandingPayments),
    uniqueIndex('bank_reconciliations_bank_account_as_of_uq')
      .on(t.bankAccountId, t.asOf)
      .where(live(t)),
  ],
);
